/* Browser-console optional structure check; no visual/hardware certification. */
window.HiyoriSmokeTest={run(){const model=createHiyoriPrototype({compatible:true}),u=model.userData,checks=[];const check=(name,pass)=>checks.push({name,pass:!!pass});let meshes=0,sprites=0;model.traverse(o=>{meshes+=!!o.isMesh;sprites+=!!o.isSprite;});check('mesh rig',meshes>50&&sprites===0);check('independent leg pivots',u.limbs[0]!==u.limbs[1]);PlazaHeroModels.animate(model,{time:1000,dt:.1,moving:true});check('opposite leg rotation',Math.abs(u.limbs[0].rotation.x+u.limbs[1].rotation.x)<.0001);for(const expression of ['normal','smile','surprise'])u.updateLook({expression});check('all expressions initialize',u.expression==='surprise');console.table(checks);return checks;}};
